import React from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Database } from 'lucide-react'

const TMFDocumentBrowser = ({ onDocumentSelect, onClose }) => {
  const selectSample = () => {
    const blob = new Blob(['tmf sample file'], { type: 'application/pdf' })
    const file = new File([blob], 'tmf-sample.pdf', { type: 'application/pdf' })
    onDocumentSelect?.({
      name: 'tmf-sample.pdf',
      file,
      mimeType: 'application/pdf',
    })
  }

  return (
    <Card className="border border-slate-200">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Database className="w-4 h-4" />
          TMF Document Browser
        </CardTitle>
        <CardDescription>Select a TMF document to import into this package.</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="flex gap-2">
          <Button type="button" onClick={selectSample}>Select Sample</Button>
          <Button type="button" variant="outline" onClick={onClose}>Close</Button>
        </div>
      </CardContent>
    </Card>
  )
}

export default TMFDocumentBrowser

